const pairSumOrLess = (nums, target) => {
  let result = [-1, -1];
  let maxSum = -1;
  nums.sort((a, b) => a - b);

  let left = 0;
  let right = nums.length - 1;

  while (left < right) {
    const sum = nums[left] + nums[right];

    if (sum <= target) {
      if (sum > maxSum) {
        maxSum = sum;
        result = [nums[left], nums[right]];
      }
      left++;
    } else {
      right--;
    }
  }

  return result;
};

