class Thing {
  constructor(name) {
    this.name = name;
    this.properties = {};
  }

  isA(type) {
    this.type = type;
    return this;
  }

  hasA(propertyName) {
    return {
      of: (propertyValue) => {
        this.properties[propertyName] = propertyValue;
        return this;
      },
    };
  }

  says(str) {
    this.say = () => str;
    return this;
  }
}

